package com.tproject.workshop.integration.controller;

import static org.assertj.core.api.Assertions.assertThat;

import com.tproject.workshop.integration.support.AbstractIntegrationTest;
import io.restassured.RestAssured;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.test.context.TestPropertySource;

/**
 * Exports the OpenAPI document generated by SpringDoc to {@code build/openapi/openapi.json}, the
 * input of the Spectral lint in CI (see {@code .spectral.yaml}). SpringDoc is closed by default;
 * this test is the only place that opens it outside the local profile.
 */
@TestPropertySource(properties = "springdoc.api-docs.enabled=true")
class OpenApiExportIT extends AbstractIntegrationTest {

    private static final Path OUTPUT = Path.of("build", "openapi", "openapi.json");

    @Test
    @DisplayName(
            "GET /v3/api-docs returns the OpenAPI document and writes it for the Spectral lint")
    void shouldExportOpenApiDocument() throws IOException {
        String body =
                RestAssured.given(SPEC)
                        .when()
                        .get("/v3/api-docs")
                        .then()
                        .statusCode(200)
                        .extract()
                        .asString();

        assertThat(body).contains("\"openapi\"").contains("\"paths\"");

        Files.createDirectories(OUTPUT.getParent());
        Files.writeString(OUTPUT, body, StandardCharsets.UTF_8);
    }
}
